phase("核对");
// 闸文件：用例在启动轮收尾之后才写它，升级通知因此唤起自己的一轮，不并进启动轮。
await world.run("node", ["-e", "const fs = require(\"node:fs\"); const timer = setInterval(() => { if (fs.existsSync(\"{{e2eRuntimeRoot}}/dwq-gate\")) clearInterval(timer); }, 100);"], { output: "discard", timeoutMs: 600000 });
const verdict = await agent("核对员").ask("E2E_DWQ_TASK 核对发布清单，给出一句结论；拿不准按哪份清单时用 escalate 问主代理。");
return { verdict };
